        sz = fallback
        return box(name or ("fb_" + key), sz, (loc[0], loc[1], loc[2] + sz[2] / 2), mat("fallback", (0.5, 0.1, 0.1)), rot=(0, 0, rotz))
    coll, dims = a
    s = 1.0
    if scale: s = scale
    elif height: s = height / max(dims.z, 1e-4)
    elif width: s = width / max(dims.x, 1e-4)
    elif length: s = length / max(dims.y, 1e-4)
    o = bpy.data.objects.new(name or ("i_" + key), None)
    o.instance_type = "COLLECTION"; o.instance_collection = coll
    o.location = loc; o.rotation_euler = rot or (0, 0, rotz); o.scale = (s, s, s)
    if parent: o.parent = parent
    return link(o)

def copy_asset(key, name, height=None, width=None):
    """append a fresh, independent copy (for animated / deformed objects). Returns (root_empty, objs, dims)"""
    p = asset_path(key)
    if not p: return None
    try:
        objs = _load(p)
    except Exception as e:
        NOTES.append("copy " + key + " " + type(e).__name__); return None
    keep = []
    for o in objs:
        if o.type in ("CAMERA", "LIGHT") or is_widget(o): continue
        nm = o.name.lower()
        if any(w in nm for w in HIDE_WORDS) and o.type == "MESH": continue
        ROOT.objects.link(o); keep.append(o)
    bpy.context.view_layer.update()
    mn, mx = bbox_of(keep)
    dims = mx - mn
    s = 1.0
    if height: s = height / max(dims.z, 1e-4)
    elif width: s = width / max(dims.x, 1e-4)
    root = empty(name)
    c = Vector(((mn.x + mx.x) / 2, (mn.y + mx.y) / 2, mn.z))
    for o in keep:
        if o.parent is None:
            mw = o.matrix_world.copy()
            o.parent = root
            o.matrix_parent_inverse = Matrix.Translation(-c)
    root.scale = (s, s, s)
    return root, keep, dims


